def rowscore(b, r):
    g = b.grid
    if g[r][3] != 2 or g[r][4] != 2:
        return 0.0
    s = 2.0
    if g[r][5] == 1:
        s += 2.0
    elif g[r][5] == 2:
        s -= 1.0
    if g[r][2] == 2:
        s -= 1.0
    return s

def score(b):
    best = 0.0
    for r in range(6):
        best = max(best, rowscore(b, r))
    if best == 0:
        return 0.0
    if b.their_playable_wins:
        best -= 2.0
    h1 = b.heights[1]
    best *= [1.0, 0.8, 0.65, 0.5, 0.4, 0.3, 0.3][h1]
    return best

def fires(b):
    return score(b) >= 2.5

def level(b):
    s = score(b)
    if s < 1.0:
        return 0
    return max(0, min(9, int(s * 2)))

def score(b):
    g = b.grid
    if b.heights[1] > 1 or b.their_playable_wins:
        return 0
    m1 = g[0][3] == 2 and g[0][4] == 2 and g[0][5] == 1 and g[0][2] != 2
    m2 = g[2][2] == 2 and g[1][2] == 1
    if not (m1 or m2):
        return 0
    s = 2 if (m1 and m2) else 1
    for (r, c) in ((0, 0), (0, 3), (0, 4), (1, 3), (1, 4), (2, 2)):
        if g[r][c] == 2:
            s += 1
    if g[0][5] == 1: s += 1
    if b.heights[1] == 1: s -= 1
    if b.ply > 20: s -= 2
    return s

def fires(b):
    return score(b) >= 4

def level(b):
    return max(0, min(9, 2 * score(b) - 4))
